import { plainDate, plainDateTime, plainTime, recurrenceRuleToString } from '@absoluteui/core';
import { RecurrencePicker, type RecurrencePickerChangeDetail } from '@absoluteui/components/recurrence-picker';

const host = document.createElement('div');
document.body.append(host);
RecurrencePicker.create(host, {
  label: 'Repeat',
  name: 'rrule',
  start: plainDateTime(plainDate(2026, 9, 29), plainTime(9)),
  timezone: 'Europe/London',
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<RecurrencePickerChangeDetail>).detail;
  host.dataset.rule = value ? recurrenceRuleToString(value) : '';
});

import { parseRecurrenceRule, plainDate } from '@absoluteui/core';
import { RecurrencePicker } from '@absoluteui/components/recurrence-picker';

const host = document.createElement('div');
document.body.append(host);
const picker = RecurrencePicker.create(host, {
  label: 'Billing cycle',
  value: parseRecurrenceRule('FREQ=MONTHLY;BYDAY=-1FR;COUNT=12'),
  start: plainDate(2026, 1, 30),
  frequencies: ['monthly', 'yearly'],
  previewCount: 3,
});
export const text = picker.summary;
